pid_t pid = fork();

if (pid < 0) {
    /* Process Creation FAILED */
    // Handle resource cleanup or retry logic
}

if (pid == 0) {
    /* CHILD PROCESS EXECUTION CONTEXT */
    // Child's primary role: perform task, often followed by exec()
    // Code here runs ONLY in the child
    printf("Child executing...\n");
} else {
    /* PARENT PROCESS EXECUTION CONTEXT (pid > 0) */
    // Code here runs ONLY in the parent
    // Parent receives the child's PID
    printf("Parent waiting for %d\n", pid);
    waitpid(pid, NULL, 0); // Wait for child to exit
}
